algorithms.pseudocode:
function count_leading_zeros_or_ones(val: uint64) -> uint64:
    match_bit = (val >> 63) & 1
    cnt = 0
    for i in range(63, -1, -1):
        if ((val >> i) & 1) == match_bit:
            cnt += 1
        else:
            break
    return cnt

function count_trailing_zeros_or_ones(val: uint64) -> uint64:
    match_bit = val & 1
    cnt = 0
    for i in range(64):
        if ((val >> i) & 1) == match_bit:
            cnt += 1
        else:
            break
    return cnt

function generate_digest(val: uint64, reg_type: enum { INT, FP16, FP32, FP64, FLAG }) -> uint12:
    if reg_type == INT:
        // Count identical leading/trailing bits
        trailing_cnt = count_trailing_zeros_or_ones(val) & 0x3F
        leading_cnt = count_leading_zeros_or_ones(val) & 0x3F
        val_lsb = val & 0x3F
        // Overlapping XOR fold into 12 bits
        digest = trailing_cnt ^ (leading_cnt << 3) ^ (val_lsb << 6)
        return digest & 0x0FFF
    elif reg_type == FP16:
        // Val[15:13] placed at digest[5:3]
        res_fp16 = ((val >> 13) & 0x7) << 3
        return res_fp16
    elif reg_type == FP32:
        // Val[31:26] placed at digest[8:3]
        res_fp32 = ((val >> 26) & 0x3F) << 3
        return res_fp32
    elif reg_type == FP64:
        // Val[63:55] placed at digest[11:3]
        res_fp64 = ((val >> 55) & 0x1FF) << 3
        return res_fp64
    elif reg_type == FLAG:
        // Val[3:0] replicated 3 times into digest[11:0]
        flags = val & 0xF
        res_flag = flags | (flags << 4) | (flags << 8)
        return res_flag
    return 0

on decode(inst):
    // Invalidate stale digests after 256 decoded instructions
    for r = 0 to 64:
        if Register_Tracking_Table[r].valid == 1:
            if Register_Tracking_Table[r].decay_ctr == 0:
                Register_Tracking_Table[r].valid = 0
            else:
                Register_Tracking_Table[r].decay_ctr -= 1

    if inst writes dst_reg:
        Register_Tracking_Table[dst_reg].valid = 0
        Register_Tracking_Table[dst_reg].payload = inst.rob_idx & 0x3FFF
        Register_Tracking_Table[dst_reg].decay_ctr = 255

on execution_complete(inst, dst_reg, result_val, reg_type):
    // Match in-flight tag
    if Register_Tracking_Table[dst_reg].valid == 0 and Register_Tracking_Table[dst_reg].payload == (inst.rob_idx & 0x3FFF):
        Register_Tracking_Table[dst_reg].payload = generate_digest(result_val, reg_type)
        Register_Tracking_Table[dst_reg].valid = 1
        Register_Tracking_Table[dst_reg].decay_ctr = 255

on pipeline_flush(squashed_rob_mask):
    for r = 0 to 64:
        if Register_Tracking_Table[r].valid == 0 and squashed(Register_Tracking_Table[r].payload):
            Register_Tracking_Table[r].payload = 0

function update_sR(pc: uint64, taken: bool, sc_mispredicted: bool, lsum: int, theta: int):
    // SC training condition: misprediction or low confidence (|lsum| <= theta)
    sc_needs_train = sc_mispredicted or (abs(lsum) <= theta)

    for bank = 0 to 7:
        if selected_valid_regs[bank] is empty:
            continue

        // Per paper Section 4.2: if multiple registers were available, randomly select one for update
        chosen_r = randomly_select(selected_valid_regs[bank])
        reg_pos = index of chosen_r in bank
        digest = recorded_digest[bank][chosen_r]

        // Update prediction weight tables WT0, WT1, WT2 if SC needs training
        if sc_needs_train:
            h0 = hash_wt0(pc, digest)
            h1 = hash_wt1(pc, digest)
            h2 = hash_wt2(pc, digest)
            update_saturating_counter(WT_Prediction_Weight_Tables[bank].WT0[h0], taken, -32, 31)
            update_saturating_counter(WT_Prediction_Weight_Tables[bank].WT1[h1], taken, -32, 31)
            update_saturating_counter(WT_Prediction_Weight_Tables[bank].WT2[h2], taken, -32, 31)

        // Update usefulness tables (UT0, UT1, UT2)
        // Increment usefulness if predicting with this register agrees with actual outcome
        idx0 = hash_ut0(pc); idx1 = hash_ut1(pc); idx2 = hash_ut2(pc)
        pred_agree = ((w0 + w1 + w2 >= 0) == taken)
        update_saturating_counter(UT_Usefulness_Tables[bank].UT0[idx0][reg_pos], pred_agree, -32, 31)
        update_saturating_counter(UT_Usefulness_Tables[bank].UT1[idx1][reg_pos], pred_agree, -32, 31)
        update_saturating_counter(UT_Usefulness_Tables[bank].UT2[idx2][reg_pos], pred_agree, -32, 31)
